 18→func TestCompact_SimpleConversation(t *testing.T) {
 19→	t.Parallel()
 20→
 21→	input := []byte(`{"type":"user","uuid":"u1","timestamp":"2026-01-01T00:00:00Z","parentUuid":"","cwd":"/repo","message":{"content":"hello"}}
 22→{"type":"assistant","timestamp":"2026-01-01T00:00:01Z","requestId":"req-1","message":{"id":"msg-1","content":[{"type":"text","text":"Hi!"}]}}
 23→`)
 24→
 25→	expected := []string{
 26→		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"user","ts":"2026-01-01T00:00:00Z","content":"hello"}`,
 27→		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"assistant","ts":"2026-01-01T00:00:01Z","id":"msg-1","content":[{"type":"text","text":"Hi!"}]}`,
 28→	}
 29→
 30→	result, err := Compact(input, defaultOpts)
 31→	if err != nil {
 32→		t.Fatalf("unexpected error: %v", err)
 33→	}
 34→	assertJSONLines(t, result, expected)
 35→}
