181→// --- Field order test (exact byte comparison since marshalOrdered is deterministic) ---
182→
183→func TestCompact_FieldOrder(t *testing.T) {
184→	t.Parallel()
185→
186→	input := []byte(`{"type":"user","uuid":"u1","timestamp":"2026-01-01T00:00:00Z","message":{"content":"hello"}}
187→`)
188→
189→	result, err := Compact(input, defaultOpts)
190→	if err != nil {
191→		t.Fatalf("unexpected error: %v", err)
192→	}
193→
