309→// --- Helpers ---
310→
311→func nonEmptyLines(data []byte) []string {
312→	var lines []string
313→	for _, line := range strings.Split(string(data), "\n") {
314→		if strings.TrimSpace(line) != "" {
315→			lines = append(lines, line)
316→		}
317→	}
318→	return lines
319→}
320→
321→// assertJSONLines compares actual output lines against expected JSON strings,
322→// using semantic JSON equality (order-independent for object keys).
323→func assertJSONLines(t *testing.T, actual []byte, expected []string) {
324→	t.Helper()
325→
326→	actualLines := nonEmptyLines(actual)
327→
328→	if len(expected) == 0 && len(actualLines) == 0 {
329→		return
330→	}
331→
332→	if len(actualLines) != len(expected) {
333→		t.Fatalf("line count mismatch: got %d, want %d\nactual:\n%s", len(actualLines), len(expected), string(actual))
334→	}
335→
336→	for i := range expected {
337→		var got, want interface{}
338→		if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
339→			t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
340→		}
341→		if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
342→			t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
343→		}
344→		if !reflect.DeepEqual(got, want) {
345→			prettyGot, _ := json.MarshalIndent(got, "", "  ")
346→			prettyWant, _ := json.MarshalIndent(want, "", "  ")
347→			t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
348→		}
349→	}
350→}
