 18→// GetTranscriptPosition returns the current line count of a Cursor transcript.
 19→// Cursor uses the same JSONL format as Claude Code, so position is the number of lines.
 20→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
 21→// Returns 0 if the file doesn't exist or is empty.
 22→func (c *CursorAgent) GetTranscriptPosition(path string) (int, error) {
 23→	if path == "" {
 24→		return 0, nil
 25→	}
 26→
 27→	file, err := os.Open(path) //nolint:gosec // Path comes from Cursor transcript location
 28→	if err != nil {
 29→		if os.IsNotExist(err) {
 30→			return 0, nil
 31→		}
 32→		return 0, fmt.Errorf("failed to open transcript file: %w", err)
 33→	}
 34→	defer file.Close()
 35→
 36→	reader := bufio.NewReader(file)
 37→	lineCount := 0
 38→
 39→	for {
 40→		line, err := reader.ReadBytes('\n')
 41→		if err != nil {
 42→			if err == io.EOF {
 43→				if len(line) > 0 {
 44→					lineCount++ // Count final line without trailing newline
 45→				}
 46→				break
 47→			}
 48→			return 0, fmt.Errorf("failed to read transcript: %w", err)
 49→		}
 50→		lineCount++
 51→	}
 52→
 53→	return lineCount, nil
 54→}
